mapper.delete:

delete from region_daily_stat
where stat_date = #{statDate,jdbcType=DATE}
  and region_id = #{regionId,jdbcType=VARCHAR}

mapper.select:

select stat_date, region_id, sido_name, `name`, total_sites, total_target, completed_target, 
cumulative_completed_target, total_reports, completed_reports, pending_reports, refused_reports, issue_reports_count, create_time
from region_daily_stat
where stat_date = #{statDate,jdbcType=DATE}
  and region_id = #{regionId,jdbcType=VARCHAR}

select count(*)
from region_daily_stat
where stat_date >= #{startDate,jdbcType=DATE}
  and stat_date <= #{endDate,jdbcType=DATE}
